<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Aluno');
$id_aluno=$_SESSION['id_usuario'];$id_questionario=intval($_GET['id']??$_POST['id']??0);if($id_questionario<=0){header('Location: questionarios_aluno.php');exit();}$mensagem='';
$stmt=$conexao->prepare('SELECT q.id_questionario,q.titulo,q.descricao FROM questionario q WHERE q.id_questionario=?');$stmt->bind_param('i',$id_questionario);$stmt->execute();$questionario=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$questionario){header('Location: questionarios_aluno.php');exit();}
$perguntas=[];$stmt=$conexao->prepare('SELECT id_pergunta,enunciado FROM pergunta WHERE id_questionario=? ORDER BY id_pergunta');$stmt->bind_param('i',$id_questionario);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$perguntas[]=$row;}$stmt->close();$ids=array_column($perguntas,'id_pergunta');$alternativas=[];if($ids){$placeholders=implode(',',array_fill(0,count($ids),'?'));$tipos=str_repeat('i',count($ids));$stmt=$conexao->prepare("SELECT id_pergunta,texto FROM alternativa WHERE id_pergunta IN ($placeholders) ORDER BY id_alternativa");$stmt->bind_param($tipos,...$ids);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$alternativas[$row['id_pergunta']][]=$row['texto'];}$stmt->close();}
$respondido=false;$respostas=[];$stmt=$conexao->prepare('SELECT r.id_pergunta,r.resposta FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta WHERE p.id_questionario=? AND r.id_usuario=?');$stmt->bind_param('ii',$id_questionario,$id_aluno);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$respondido=true;$respostas[$row['id_pergunta']]=$row['resposta'];}$stmt->close();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['enviar'])&&!$respondido){$enviadas=$_POST['resposta']??[];$validas=[];foreach($perguntas as $pergunta){$id_pergunta=(int)$pergunta['id_pergunta'];$valor=trim($enviadas[$id_pergunta]??'');if($valor===''){$mensagem='<div class="notice error" role="alert">Responda todas as perguntas antes de enviar.</div>';break;}if(!empty($alternativas[$id_pergunta])&&!in_array($valor,$alternativas[$id_pergunta],true)){$mensagem='<div class="notice error" role="alert">Uma das respostas selecionadas não é válida.</div>';break;}$validas[$id_pergunta]=$valor;}if(!$mensagem&&$validas){$conexao->begin_transaction();$ok=true;$stmt=$conexao->prepare('SELECT COUNT(*) AS total FROM resposta r JOIN pergunta p ON p.id_pergunta=r.id_pergunta WHERE p.id_questionario=? AND r.id_usuario=?');$stmt->bind_param('ii',$id_questionario,$id_aluno);$stmt->execute();$duplicado=(int)$stmt->get_result()->fetch_assoc()['total']>0;$stmt->close();if($duplicado){$ok=false;$conexao->rollback();$mensagem='<div class="notice warn" role="status">Este questionário já foi respondido.</div>';}else{$insert=$conexao->prepare('INSERT INTO resposta (id_pergunta,id_usuario,resposta) VALUES (?,?,?)');foreach($validas as $id_pergunta=>$valor){$insert->bind_param('iis',$id_pergunta,$id_aluno,$valor);if(!$insert->execute()){$ok=false;break;}}$insert->close();if($ok){$conexao->commit();$respondido=true;$respostas=$validas;$mensagem='<div class="notice success" role="status">Questionário enviado com sucesso.</div>';}else{$conexao->rollback();$mensagem='<div class="notice error" role="alert">Não foi possível enviar o questionário.</div>';}}}}
function atlas_escape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
