.btn.secondary:hover{background:#f6f6ff}.btn:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #aaa9ff;outline-offset:2px}.notice{padding:15px 18px;border-radius:12px;font-size:12px;line-height:1.65;margin-bottom:20px;background:#f0efff;color:#5553a7;border:1px solid #dfdefb}.notice.error{background:#fff0f0;color:#a63842;border-color:#f6dadd}.notice.success{background:#eaf8ef;color:#28754a;border-color:#d4eddd}.notice.warn{background:#fff7ea;color:#98601b;border-color:#f3e5c8}.search{width:min(310px,100%);border:1px solid #e3e5ee;background:#fafbfe;border-radius:9px;padding:10px 12px;color:var(--ink);font-size:12px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:20px 24px;border-bottom:1px solid var(--line)}.toolbar strong{font-size:13px}.muted{color:var(--muted)}[hidden]{display:none!important}@media(max-width:800px){.atlas-main{padding:76px 18px 35px}.heading{align-items:start;flex-direction:column}.toolbar{flex-wrap:wrap}.search{width:100%}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
</style><style>.back-link{font-size:12px;color:#6664df;font-weight:650;text-decoration:none}.detail-card{overflow:hidden}.question{border:0;border-bottom:1px solid var(--line);padding:26px 30px;margin:0;min-width:0}.question:last-of-type{border-bottom:0}.question legend{display:flex;align-items:center;gap:13px;width:100%;font-size:14px;font-weight:700;line-height:1.6;padding:0;float:left;margin-bottom:18px}.question legend:after{content:"";display:block;clear:both}.number{width:31px;height:31px;display:inline-grid;place-items:center;flex:none;border-radius:9px;background:#f0efff;color:#6664df;font-size:11px;font-weight:750}.option{display:flex;align-items:center;gap:12px;margin:9px 0;padding:14px 16px;border:1px solid #e7e9f1;border-radius:11px;font-size:12px;color:#555c71;cursor:pointer;clear:both}.option:hover{border-color:#aaa9ef;background:#fafaff}.option:has(input:checked){border-color:#a8a6f5;background:#f7f6ff;color:#39378b}.option input{accent-color:#6664df;width:16px;height:16px;flex:none}.option:has(input:disabled){cursor:default}.answer{display:block;clear:both;width:100%;resize:vertical;min-height:110px;padding:15px;border:1px solid #e3e5ee;border-radius:10px;background:#fafbfe;color:var(--ink);font-size:12px;line-height:1.7}.answer:disabled{color:#5d6477}.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:24px 30px;border-top:1px solid var(--line)}@media(max-width:600px){.question{padding:20px 17px}.actions{padding:20px 17px}.question legend{font-size:13px}}</style></head><body>
