<main class="atlas-main"><div class="topline"><span class="eyebrow">INSTITUTO ATLAS / QUESTIONÁRIOS</span><a class="back-link" href="questionarios_aluno.php">← Todos os questionários</a></div><header class="heading"><div><h1><?php echo atlas_escape($questionario['titulo']); ?></h1><p><?php echo atlas_escape($questionario['descricao']??''); ?></p></div><span class="tag"><?php echo $respondido?'Concluído':'Para responder'; ?></span></header>
<?php echo $mensagem; ?><?php if($respondido): ?><div class="notice">Este questionário já foi respondido. Suas respostas estão disponíveis somente para consulta.</div><?php endif; ?>
<div class="section-head"><div><h2>Perguntas</h2><p><?php echo count($perguntas); ?> <?php echo count($perguntas)===1?'pergunta':'perguntas'; ?> neste questionário</p></div><span class="count"><?php echo $respondido?'Respondido':'Em andamento'; ?></span></div>
<section class="card detail-card"><form method="post" id="question-form"><input type="hidden" name="id" value="<?php echo (int)$id_questionario; ?>">
<?php foreach($perguntas as $indice=>$pergunta):$id_pergunta=(int)$pergunta['id_pergunta']; ?><fieldset class="question"><legend><span class="number"><?php echo str_pad((string)($indice+1),2,'0',STR_PAD_LEFT); ?></span><?php echo atlas_escape($pergunta['enunciado']); ?></legend>
<?php if(!empty($alternativas[$id_pergunta])):foreach($alternativas[$id_pergunta] as $opcao): ?><label class="option"><input type="radio" name="resposta[<?php echo $id_pergunta; ?>]" value="<?php echo atlas_escape($opcao); ?>" <?php echo (($respostas[$id_pergunta]??'')===$opcao)?'checked':''; ?> <?php echo $respondido?'disabled':''; ?>><span><?php echo atlas_escape($opcao); ?></span></label><?php endforeach;else: ?><textarea class="answer" name="resposta[<?php echo $id_pergunta; ?>]" rows="4" placeholder="Escreva sua resposta aqui..." <?php echo $respondido?'disabled':''; ?>><?php echo atlas_escape($respostas[$id_pergunta]??''); ?></textarea><?php endif; ?></fieldset><?php endforeach; ?>
<?php if(!$perguntas): ?><div class="empty">Nenhuma pergunta disponível.</div><?php endif; ?><div class="actions"><?php if($perguntas&&!$respondido): ?><button class="btn" name="enviar" value="1" type="submit">Enviar respostas →</button><?php endif; ?><a class="btn secondary" href="questionarios_aluno.php">Voltar à lista</a></div></form></section><div class="footer">Instituto Atlas · Portal acadêmico</div></main></body></html>
